<?php
declare(strict_types=1);
namespace App\Interface\Http\Review\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Review\Mapper\ReviewResponseMapper;use App\Application\Review\Service\BuildReviewSessionService;use App\Domain\Review\Enum\ReviewSessionKind;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class ReviewSessionController { public function __construct(private AuthService $auth,private BuildReviewSessionService $sessions,private ReviewResponseMapper $mapper,private ApiResponseFactory $responses){} public function get(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,ReviewSessionKind $kind,int $limit):ResponseInterface{try{$user=$this->auth->currentUser($access);$session=$this->sessions->execute($user->id,$kind,$limit,new \DateTimeImmutable('now'));return $this->responses->success($p,$this->mapper->session($session),(string)$r->getAttribute('request_id'));}catch(\InvalidArgumentException){return $this->responses->problem($p,'VALIDATION_FAILED','Limite de revisão inválido.',422,(string)$r->getAttribute('request_id'));}catch(\DomainException){return $this->responses->problem($p,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}} }
